  let result = '';
  let carry = 0;

  // Initialize pointers for the two numbers
  let i = num1.length - 1;
  let j = num2.length - 1;

  // Loop through the numbers from right to left
  while (i >= 0 || j >= 0 || carry > 0) {
    // Calculate the sum of the current digits and the carry
    let sum = carry;
    if (i >= 0) {
      sum += parseInt(num1[i]);
      i--;
    }
    if (j >= 0) {
      sum += parseInt(num2[j]);
      j--;
    }

    // Update the result and the carry
    result = (sum % 10).toString() + result;
    carry = Math.floor(sum / 10);
  }

  return result;
}

